import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture, vec2, vec3, mix, sin, fract, dot, clamp, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, Color, DoubleSide } = THREE;

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headline =
    items.find((i) => i.role === 'headline')?.text ?? 'Features 1';
  const headlineFontSize =
    items.find((i) => i.role === 'headline')?.typography?.fontSize ?? 39;

  const root = new Group();
  root.name = 'features-card-1-label';

  const content = new Group();
  root.add(content);

  // --- Card plaque geometry (aspect derived from atlas source rect 512x320) ---
  const rectW = 512;
  const rectH = 320;
  const aspect = rectW / rectH;
  const cardHeight = 0.72;
  const cardWidth = cardHeight * aspect * 0.62; // scale down to a label-plaque footprint

  const geometry = new PlaneGeometry(cardWidth, cardHeight, 1, 1);

  const inkColor = vec3(new Color(colors.ink));
  const surfaceColor = vec3(new Color(colors.surface));

  const material = new MeshBasicNodeMaterial();
  material.side = DoubleSide;
  material.transparent = true;

  let texRef = null;

  // engineered vertical gradient (surface -> ink) + subtle grain
  const uvNode = uv();
  const gradT = clamp(uvNode.y, 0.0, 1.0);
  const gradColor = mix(surfaceColor, inkColor, gradT);

  const grainSeed = dot(uvNode.mul(1571.0), vec2(12.9898, 78.233));
  const grain = fract(sin(grainSeed).mul(43758.5453));
  const grainAmt = grain.sub(0.5).mul(0.035);

  material.colorNode = gradColor.add(grainAmt);
  material.opacityNode = float(0.96);

  const plaque = new Mesh(geometry, material);
  content.add(plaque);

  // accent underline bar (<=10% of frame area, single accent presence)
  const barGeo = new PlaneGeometry(cardWidth * 0.42, 0.028, 1, 1);
  const barMat = new MeshBasicNodeMaterial();
  barMat.colorNode = vec3(new Color(colors.accent));
  const bar = new Mesh(barGeo, barMat);
  bar.position.set(-cardWidth * 0.5 + cardWidth * 0.21 + 0.02, -cardHeight * 0.5 + 0.09, 0.01);
  content.add(bar);

  // headline text (JetBrains Mono / Lora display substitute via fontAtlas)
  const label = ctx.fontAtlas.createText(String(headline), {
    fontSize: headlineFontSize,
    color: colors.paper,
    align: 'left',
    maxWidthPx: 420,
  });
  label.position.set(-cardWidth * 0.5 + 0.06, cardHeight * 0.5 - 0.24, 0.02);
  content.add(label);

  // load the decorative isolated image at low blend, subordinate to gradient
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      texRef = tex;
      const texSample = texture(tex, uvNode);
      material.colorNode = mix(gradColor.add(grainAmt), texSample.rgb, 0.14);
      material.opacityNode = clamp(texSample.a.add(0.6), 0.0, 0.96);
      material.needsUpdate = true;
    }).catch(() => {});
  }

  // --- motion: weighted rise-in entrance on inner content group ---
  content.position.y -= 0.32;
  content.scale.setScalar(0.98);

  const tl = gsap.timeline();
  tl.to(content.position, {
    y: content.position.y + 0.32,
    duration: 0.7,
    ease: 'power3.out',
  });
  tl.to(content.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.9,
    ease: 'power4.out',
  }, 0.1);

  // idle: single slow breathing transform (<=2%)
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true, delay: 0.8 });
  idleTl.to(content.scale, {
    x: 1.015,
    y: 1.015,
    z: 1.015,
    duration: 2.6,
    ease: 'sine.inOut',
  });

  // apply configured cinematic primitives (none specified for this node)
  const primitiveHandles = [];
  const primitives = Array.isArray(config.cinematicPrimitives)
    ? config.cinematicPrimitives
    : [];
  for (const prim of primitives) {
    const fn = ctx.primitives?.[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(root, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    idleTl.kill();
    for (const h of primitiveHandles) {
      h?.cleanup?.();
    }
    geometry.dispose();
    material.dispose();
    barGeo.dispose();
    barMat.dispose();
    if (texRef && typeof texRef.dispose === 'function') {
      texRef.dispose();
    }
    if (label?.userData?.cleanup) {
      label.userData.cleanup();
    } else if (label?.geometry) {
      label.geometry.dispose?.();
      label.material?.dispose?.();
    }
  };

  return root;
}
